//! JSON Schema (draft 2020-12) generation for the delta format.

use super::{Annotation, DeltaDocument, FormField, Op, SignatureEntity};
use schemars::generate::SchemaSettings;
use serde_json::{json, Value};

pub const SCHEMA_ID: &str = "https://nib-pdf.dev/schema/nib-delta-v1.json";

/// Builds the draft 2020-12 schema rooted at [`DeltaDocument`]. `$defs`
/// contains the payload families (`Op`, `Annotation`, `FormField`,
/// `SignatureEntity`) generated by the same generator so shared subschemas
/// are merged.
pub fn delta_schema() -> Value {
    let mut generator = SchemaSettings::draft2020_12().into_generator();
    // Make sure the payload families land in `$defs` even though `Op.payload`
    // is untyped.
    generator.subschema_for::<Op>();
    generator.subschema_for::<Annotation>();
    generator.subschema_for::<FormField>();
    generator.subschema_for::<SignatureEntity>();
    let root = generator.root_schema_for::<DeltaDocument>();
    let mut v = root.to_value();
    let obj = v.as_object_mut().expect("root schema is an object");
    obj.insert("$id".into(), json!(SCHEMA_ID));
    obj.insert("title".into(), json!("Nib PDF delta v1"));
    v
}

/// The schema file contents (pretty JSON + trailing newline).
pub fn delta_schema_string() -> String {
    let mut s = serde_json::to_string_pretty(&delta_schema()).expect("schema serialises");
    s.push('\n');
    s
}
